ROLE_PROVIDERS = [
    "openrouter_claude_opus",
    "opencode_claude",
    "openrouter_claude_sonnet",
    "deepseek_native_flash",  # Per 17R amendment
    "opencode_deepseek",
    "opencode",
    "opencode_minimax"
]

ROTATION_TAIL_PROVIDERS = []

def load_tail_providers():
    """Load tail providers from config file"""
    config_path = os.path.join(os.path.dirname(__file__), "..", "config", "tail_providers.json")
    if os.path.exists(config_path):
        with open(config_path, "r") as f:
            ROTATION_TAIL_PROVIDERS.extend(json.load(f))

def get_provider_for_role(role: str) -> Optional[str]:
    """Get provider for role with priority ordering"""
    load_tail_providers()
    
    # Check primary providers first
    for provider in ROLE_PROVIDERS:
        if is_provider_available(provider, role):
            return provider
    
    # Fallback to tail providers
    for provider in ROTATION_TAIL_PROVIDERS:
        if is_provider_available(provider, role):
            return provider
    
    return None

