# scripts/add_provider.py
import json
from pathlib import Path
import shutil

EVALUATION_DIR = Path(__file__).parent.parent / "core" / "ai" / "evaluations"
CONFIG_DIR = Path(__file__).parent.parent / "config"

def add_approved_provider(provider_name: str):
    """Add provider to tail rotation if approved"""
    evaluation_path = EVALUATION_DIR / f"{provider_name}_evaluation.json"
    
    if not evaluation_path.exists():
        print(f"Evaluation not found for {provider_name}")
        return
        
    with open(evaluation_path, "r") as f:
        evaluation = json.load(f)
        
    if not evaluation.get("approved"):
        print(f"Provider {provider_name} not approved")
        return
        
    config_path = CONFIG_DIR / "tail_providers.json"
    
    # Create config file if it doesn't exist
    if not config_path.exists():
        config_path.touch()
        
    with open(config_path, "r+") as f:
        providers = json.load(f)
        if provider_name not in providers:
            providers.append(provider_name)
            f.seek(0)
            json.dump(providers, f, indent=2)
            f.truncate()
            
    print(f"Added {provider_name} to tail providers")

