def test_provider_rotation_order():
    from core.ai.ai_router import ROLE_PROVIDERS, ROTATION_TAIL_PROVIDERS
    
    # Ensure all tail providers come after primary providers
    for tail_provider in ROTATION_TAIL_PROVIDERS:
        assert tail_provider not in ROLE_PROVIDERS
        assert all(ROLE_PROVIDERS.index(p) < len(ROLE_PROVIDERS) for p in ROTATION_TAIL_PROVIDERS)

